mutations.find:
const next = new Map<string, number>();
for (const { channel, messages } of chans)
  if (!isEventChannel(channel)) next.set(channel, messages);
this.channelCounts = next;

mutations.replace:
const next = new Map<string, number>(this.channelCounts);
for (const { channel, messages } of chans)
  if (!isEventChannel(channel)) next.set(channel, messages);
this.channelCounts = next;
